from pathlib import Path
import base64, html
P=Path('/home/user/PMDO-Destiny-guilde/Mega-Tsareena-PMD/Frames-IA')
def data(name):
 return 'data:image/png;base64,'+base64.b64encode((P/name).read_bytes()).decode()
rows=[('Face','Walk-face-02.png','Pose validée précédemment'),('Avant droite','Walk-avant-droite-01.png','Modèle de référence'),('Droite','Unifie-droite-01.png','Nouvelle vue de profil'),('Arrière droite','Harmonise-arriere-droite-02.png','Reprise harmonisée avec l’arrière gauche'),('Dos','Harmonise-dos-01.png','Trois mèches reprises pour le dos'),('Arrière gauche','Harmonise-arriere-gauche-02.png','Reprise harmonisée avec l’arrière droit'),('Gauche','Unifie-gauche-01-reprise.png','Reprise depuis le profil droit'),('Avant gauche','Walk-avant-gauche-corrige-01.png','Reprise depuis l’avant droit')]
style='''body{margin:0;background:#f1f6ed;color:#284332;font:15px system-ui,sans-serif}main{max-width:1250px;margin:auto;padding:30px 24px}header{font-size:11px;text-transform:uppercase;letter-spacing:.14em;color:#759175;font-weight:700}h1{font:700 38px Georgia,serif;margin:12px 0}p{line-height:1.6;color:#617862}.notice{background:#fff8e7;color:#715928;padding:14px 17px;border-radius:12px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{margin:0;background:white;border:1px solid #dfe9da;border-radius:14px;padding:10px}.card img{display:block;width:100%;height:320px;object-fit:contain;image-rendering:pixelated;background:#f1f1ed}.card figcaption{padding:10px 4px;font-weight:700}.card small{display:block;color:#788b79;font-weight:400;margin-top:4px}button{padding:10px 16px;border:1px solid #aabdab;border-radius:8px;background:white;color:#284332;cursor:pointer}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.pair img{width:100%;height:520px;object-fit:contain;image-rendering:pixelated;background:#eee}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}.card img{height:250px}.pair img{height:340px}}'''
items=''.join(f'<figure class="card"><img src="{data(name)}" alt="{html.escape(label)}"><figcaption>{html.escape(label)}<small>{html.escape(note)}</small></figcaption></figure>' for label,name,note in rows)
gallery=f'''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Méga-Tsareena · huit directions</title><style>{style}</style><main><header>Images IA brutes · comparatif</header><h1>Méga-Tsareena · huit directions</h1><p>Les nouvelles vues reprennent la même référence de forme, de couleurs et de style. Elles montrent une pose par direction, pas encore un cycle complet.</p><p class="notice"><b>Travail en cours :</b> les motifs, les mèches et la robe des vues arrière ont été rapprochés. Des différences de proportions et de détails persistent, et les animations de plusieurs directions restent à créer. Le damier fait partie des images et n’est pas transparent. Ces images ne sont pas une planche prête pour le jeu.</p><div class="grid">{items}</div><p>Les sorties originales sont conservées sans retouche. Les diagonales animées sont présentées dans le fichier « Diagonales-harmonisees.html ».</p></main></html>'''
(P/'Huit-directions-harmonisees.html').write_text(gallery)
r=['Walk-avant-droite-01.png','Harmonise-avant-droite-02.png','Harmonise-avant-droite-03.png','Walk-avant-droite-04.png']
l=['Walk-avant-gauche-corrige-01.png','Harmonise-avant-gauche-02.png','Harmonise-avant-gauche-03.png','Walk-avant-gauche-corrige-04.png']
import json
anim=f'''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Méga-Tsareena · diagonales animées</title><style>{style}</style><main><header>Images IA brutes · essais d’animation</header><h1>Avant droite et avant gauche</h1><p>Les images des deux diagonales ont été rapprochées du même modèle. Quatre poses par direction.</p><div class="pair"><figure class="card"><img id="r" alt="Avant droite"><figcaption>Avant droite</figcaption></figure><figure class="card"><img id="l" alt="Avant gauche"><figcaption>Avant gauche</figcaption></figure></div><p><button id="toggle">Pause</button> <span id="status"></span></p><p class="notice">Essai brut : les positions et détails des vêtements varient, et le mouvement vertical n’est pas régulier. Le damier est dessiné, non transparent.</p></main><script>const R={json.dumps([data(n) for n in r])}, L={json.dumps([data(n) for n in l])};let i=0,play=true;function show(){{document.getElementById('r').src=R[i];document.getElementById('l').src=L[i];document.getElementById('status').textContent='Pose '+(i+1)+' / 4'}}document.getElementById('toggle').onclick=e=>{{play=!play;e.target.textContent=play?'Pause':'Reprendre'}};show();setInterval(()=>{{if(play){{i=(i+1)%4;show()}}}},400)</script></html>'''
(P/'Diagonales-harmonisees.html').write_text(anim)
print('comparatif et animation autonomes créés')
